pub fn isKnownMethod(m: []const u8) bool {
    if (g.method_shard_0.isKnownMethod(m)) return true;
    if (g.method_shard_1.isKnownMethod(m)) return true;
    if (g.method_shard_2.isKnownMethod(m)) return true;
    if (g.method_shard_3.isKnownMethod(m)) return true;
    if (g.method_shard_4.isKnownMethod(m)) return true;
    if (g.method_shard_5.isKnownMethod(m)) return true;
    if (g.method_shard_6.isKnownMethod(m)) return true;
    if (g.method_shard_7.isKnownMethod(m)) return true;
    if (g.method_shard_8.isKnownMethod(m)) return true;
    if (g.method_shard_9.isKnownMethod(m)) return true;
    if (g.method_shard_10.isKnownMethod(m)) return true;
    if (g.method_shard_11.isKnownMethod(m)) return true;
    if (g.method_shard_12.isKnownMethod(m)) return true;
    if (g.method_shard_13.isKnownMethod(m)) return true;
    if (g.method_shard_14.isKnownMethod(m)) return true;
    return false;
}

