test "mcp methods all shards" {
    try std.testing.expect(isKnownMethod("tools/list"));
    try std.testing.expect(isKnownMethod("ext/method_0_0"));
    try std.testing.expect(isKnownMethod("ext/method_14_0"));
    try std.testing.expect(isKnownMethod("ext/method_14_49"));
    const gpa = std.testing.allocator;
    const req = try buildExtRequest(gpa, "ext/method_14_0", 9, "{}");
    try std.testing.expect(req != null);
    defer gpa.free(req.?);
    try std.testing.expect(std.mem.indexOf(u8, req.?, "ext/method_14_0") != null);
}
